/**
 * 负责运行时死亡枪选择与死因资格政策。输入为原生命句柄、死因、政策和来源阶段；
 * 输出为选择类型及原 permitsDeathShot／permitsHunterShot 结果，保持原拒绝顺序。
 * 序列化死因来自公共契约，回调、组件引用与行动权限仅留在领域内部。
 * 混合死因必须全部合格，不能用其中一项狼刀／放逐掩盖毒或关系牵连的抑制。
 */
import { Phase } from "./identity";
import type { DeathActionPolicy } from "./board";
import type { NightLifeScope } from "./night-effects";
import { DeathCause } from "@ai-werewolf-arena/game-contract";
export { DeathCause } from "@ai-werewolf-arena/game-contract";
export type { DeathSources } from "@ai-werewolf-arena/game-contract";

/** shot／pass 带原行动窗口 ID；invalid 未授权，不能被当作已付款的弃枪。 */
export type DeathShotSelection =
  | {
      kind: "shot";
      targetId: number;
      deathActionId: number;
      targetScope?: NightLifeScope;
      mappedMiss?: true;
      mappingCurrent?: () => boolean;
    }
  | { kind: "pass"; deathActionId: number }
  | { kind: "invalid" };

export function permitsDeathShot(
  sources: readonly DeathCause[],
  policy: DeathActionPolicy = "awa_qualified_sources_v1",
  deathPhase?: Phase,
): boolean {
  // day 政策先限制死亡来源为白天／放逐；knife-or-exile 不接受枪击和白狼爆炸。
  if (policy === "awa_day_deaths_v1" && deathPhase !== Phase.Day && deathPhase !== Phase.Voting)
    return false;
  if (
    policy !== "awa_qualified_sources_v1" &&
    policy !== "awa_knife_or_exile_v1" &&
    policy !== "awa_day_deaths_v1"
  )
    return false;
  // 先拒绝未知政策，再逐项校验；混合来源不以“存在一项合格”放宽枪权。
  return (
    sources.length > 0 &&
    sources.every(
      (source) =>
        source === DeathCause.WolfKill ||
        source === DeathCause.MechanicalKnife ||
        source === DeathCause.AwakenedHiddenKnife ||
        source === DeathCause.Exile ||
        (policy !== "awa_knife_or_exile_v1" &&
          (source === DeathCause.Shot || source === DeathCause.WhiteWolfBlast)),
    )
  );
}
/** 猎人兼容入口直接复用同一资格政策，不能维护第二套死因规则。 */
export const permitsHunterShot = permitsDeathShot;

/**
 * 负责维护序列化板子结构及稳定政策数据。输入为身份与政策机器值，输出 BoardConfig 类型、原政策数组和默认常量。
 * 可选配置字段表示数据格式，并不证明组合已支持；本模块不发牌、不安装角色或授予行动许可，规则集与领域分别拥有这些行为。
 */
import { EVENT_PACK_IDS } from "./event-ids";
import type {
  CatSkippedVotePolicy,
  PufferBallotPolicy,
  BearSignalPolicy,
} from "./board-policy-identifiers";
import type {
  ActionWindow,
  KnightDuelWindow,
  Role,
  WinCondition,
  WitchSelfHealRule,
  TieBreakerStrategy,
} from "./identity";

/** 仅当双方淘汰目标同时达成时使用这份显式优先级。 */
export const ELIMINATION_PRIORITIES = ["awa_good_priority_v1", "awa_wolf_priority_v1"] as const;
export type EliminationPriority = (typeof ELIMINATION_PRIORITIES)[number];

export interface HookConfig {
  onDaybreak: boolean;
  onPreElection: boolean;
  onPreVote: boolean;
  onPerSpeechGap: boolean;
}

export interface SelfDestructConfig {
  enabledWindows: ActionWindow[];
}

export const SHERIFF_ELECTION_POLICIES = [
  "awa_final_candidates_v1",
  "awa_nomination_offstage_pk_v1",
] as const;
export type SheriffElectionPolicy = (typeof SHERIFF_ELECTION_POLICIES)[number];
export const EXILE_VOTE_POLICIES = ["awa_direct_v1", "awa_one_pk_v1"] as const;
export type ExileVotePolicy = (typeof EXILE_VOTE_POLICIES)[number];
export const SHERIFF_BADGE_POLICIES = ["awa_next_seat_v1", "awa_holder_choice_v1"] as const;
export type SheriffBadgePolicy = (typeof SHERIFF_BADGE_POLICIES)[number];
export interface SheriffConfig {
  badgePolicy?: SheriffBadgePolicy;
  electionPolicy?: SheriffElectionPolicy;
  voteWeight?: number;
}

export const WITCH_KNIFE_VISIBILITY_POLICIES = ["awa_with_heal_v1", "awa_always_v1"] as const;
export type WitchKnifeVisibilityPolicy = (typeof WITCH_KNIFE_VISIBILITY_POLICIES)[number];
export const WITCH_POTION_POLICIES = [
  "awa_one_native_v1",
  "awa_both_native_experimental_v1",
] as const;
export type WitchPotionPolicy = (typeof WITCH_POTION_POLICIES)[number];
export interface WitchConfig {
  knifeVisibility?: WitchKnifeVisibilityPolicy;
  potionPolicy?: WitchPotionPolicy;
  canSelfHeal?: WitchSelfHealRule;
}

export interface TieBreakerConfig {
  exileVote?: TieBreakerStrategy;
  wolfKillVote?: TieBreakerStrategy;
  sheriffVote?: TieBreakerStrategy;
}

export const GUARD_REPEAT_POLICIES = [
  "awa_last_action_v1",
  "netease_consecutive_nights_v1",
] as const;
export type GuardRepeatPolicy = (typeof GUARD_REPEAT_POLICIES)[number];

export const HIDDEN_WOLF_CAMP_INSPECTION_POLICIES = [
  "awa_inheritance_v1",
  "netease_2020_good_v1",
] as const;
export type HiddenWolfCampInspectionPolicy = (typeof HIDDEN_WOLF_CAMP_INSPECTION_POLICIES)[number];

export const SEER_TARGET_POLICIES = ["awa_alive_v1", "awa_fresh_others_v1"] as const;
export type SeerTargetPolicy = (typeof SEER_TARGET_POLICIES)[number];
export const SEER_ACTION_POLICIES = ["awa_optional_v1", "awa_required_when_legal_v1"] as const;
export type SeerActionPolicy = (typeof SEER_ACTION_POLICIES)[number];
/** 基础夜流程要求有合法目标时完成预言家行动；各规范化路径共用这一默认值。 */
export const DEFAULT_SEER_ACTION_POLICY: SeerActionPolicy = "awa_required_when_legal_v1";

export const DEATH_ACTION_POLICIES = ["awa_qualified_sources_v1", "awa_knife_or_exile_v1"] as const;
export type HunterDeathActionPolicy = (typeof DEATH_ACTION_POLICIES)[number];
export const WOLF_KING_DEATH_ACTION_POLICIES = [
  ...DEATH_ACTION_POLICIES,
  "awa_day_deaths_v1",
] as const;
export type DeathActionPolicy = (typeof WOLF_KING_DEATH_ACTION_POLICIES)[number];
export const INSPECTION_POLICIES = [
  "awa_unique_required_v1",
  "awa_repeat_optional_v1",
  "awa_unique_optional_v1",
] as const;
export type InspectionPolicy = (typeof INSPECTION_POLICIES)[number];

export const DEATH_REVEAL_POLICIES = ["awa_hidden_v1", "netease_2017_open_v1"] as const;
export type DeathRevealPolicy = (typeof DEATH_REVEAL_POLICIES)[number];
export const LAST_WORDS_POLICIES = [
  "awa_initial_wave_v1",
  "netease_2017_day_and_first_night_v1",
] as const;
export type LastWordsPolicy = (typeof LAST_WORDS_POLICIES)[number];

export const DREAM_PROTECTION_POLICIES = [
  "awa_night_damage_v1",
  "netease_2026_night_immunity_v1",
] as const;
export type DreamProtectionPolicy = (typeof DREAM_PROTECTION_POLICIES)[number];
export const BEAUTY_DEATH_LINK_POLICIES = [
  "awa_exile_poison_v1",
  "heroes_s7_2017_exile_hunter_v1",
] as const;
export type BeautyDeathLinkPolicy = (typeof BEAUTY_DEATH_LINK_POLICIES)[number];

export const CUPID_POLICIES = [
  "netease_2017_cupid_follows_lovers_v1",
  "lui_meme_lovers_only_v1",
] as const;
export type CupidPolicy = (typeof CUPID_POLICIES)[number];

export const DEBATER_POLICIES = ["awa_melbourne_2026_speech_gap_v1"] as const;
export type DebaterPolicy = (typeof DEBATER_POLICIES)[number];

export { EVENT_PACK_IDS } from "./event-ids";
// 可选字段保留“未提供”的序列化含义；这里不把省略字段改成有效运行配置。
export interface BoardConfig {
  animalDream?: { policy: "awa_animal_dream_v1"; eliminationPriority: "awa_wolf_priority_v1" };
  whiteCat?: { skippedVotePolicy: CatSkippedVotePolicy };
  pufferfish?: { ballotPolicy: PufferBallotPolicy };
  bear?: { signalPolicy: BearSignalPolicy };
  fragrantPairSeer?: { policy: "awa_fragrant_pair_seer_v1" };
  nobleSecretBody?: { policy: "awa_noble_secret_body_v1" };
  nightNoble?: { wolfActionPolicy: "standard" | "no_blast_no_self_knife" };
  awakenedIdiot?: { protectionRepeatPolicy: "awa_nonconsecutive_nights_v1" | "awa_repeat_v1" };
  radiantEclipse?: { policy: "awa_radiant_eclipse_v1" };
  scholarMentor?: { policy: "awa_scholar_mentor_twelve_v1" };
  mistRaven?: { policy: "awa_mist_raven_v1" };
  timeConsort?: {
    policy: "awa_time_consort_reflection_v1";
    reflectionScope: "whole_night" | "first_effect";
  };
  wolfSorcerer?: { policy: "awa_wolf_sorcerer_seats_v1"; firstNight: 1 | 2 };
  trickster?: { policy: "awa_trickster_exile_v1" };
  orderPrince?: { policy: "awa_order_prince_first_ballot_v1" };
  magician?: {
    policy: "awa_magician_wolf_king_v1";
    firstNight: 1 | 2;
    deathShotTargetPolicy: "original" | "exchanged";
  };
  redMoon?: { policy: "awa_red_moon_demon_v1"; lastWolfBlastPolicy: "ends_game" | "forbidden" };
  nightmareShadow?: {
    policy: "awa_nightmare_dreamer_v1";
    fearActionPolicy: "optional" | "required_when_legal";
    wolfActionPolicy: "standard" | "no_blast_no_self_knife";
  };
  evilKnight?: {
    policy: "awa_evil_knight_v1";
    shotPolicy: "night_shot_immune" | "hunter_shot_bypasses";
  };
  pureWhite?: { policy: "awa_pure_white_night_v1"; eliminationPriority: EliminationPriority };
  wolfWitch?: { policy: "awa_pure_white_night_v1" };
  demonHunter?: { policy: "awa_netease_demon_hunter_v1" };
  events?: { pack: (typeof EVENT_PACK_IDS)[number] };
  wildChild?: { policy: "awa_lui_meme_wild_child_v1" };
  ghostBride?: { policy: "awa_melbourne_ghost_bride_v1" };
  lonelyGirl?: { policy: "awa_netease_lonely_girl_v1" };
  thief?: { policy: "lui_meme_thief_two_extra_villagers_v1" };
  shapeshifter?: { policy: "awa_netease_shapeshifter_two_extra_villagers_v1" };
  debater?: { policy: DebaterPolicy };
  cupid?: { policy: CupidPolicy };
  dreamer?: { protectionPolicy: DreamProtectionPolicy };
  wolfBeauty?: { deathLinkPolicy: BeautyDeathLinkPolicy };
  disclosure?: { deathRevealPolicy: DeathRevealPolicy };
  lastWords?: { policy: LastWordsPolicy };
  boardSize: number;
  enableSheriff: boolean;
  initialSheriffSeat?: number;
  winConditions?: WinCondition[];
  winCondition?: WinCondition;
  hooks: HookConfig;
  selfDestruct?: SelfDestructConfig;
  sheriff?: SheriffConfig;
  witch?: WitchConfig;
  seer?: { targetPolicy: SeerTargetPolicy; actionPolicy: SeerActionPolicy };
  hunter?: { deathActionPolicy: HunterDeathActionPolicy };
  wolfKing?: { deathActionPolicy: DeathActionPolicy };
  gargoyle?: { inspectionPolicy: InspectionPolicy };
  psychic?: { inspectionPolicy: InspectionPolicy };
  mirrorGirl?: { inspectionPolicy: InspectionPolicy };
  guard?: { repeatPolicy: GuardRepeatPolicy };
  hiddenWolf?: { campInspection: HiddenWolfCampInspectionPolicy };
  knight?: { enabledWindows: KnightDuelWindow[] };
  tieBreaker?: TieBreakerConfig;
  voting?: { exilePolicy: ExileVotePolicy };
  roleSetups: Array<{ role: Role; count: number }>;
}

/**
 * 负责按遗言政策判定资格，并为已死亡玩家发表遗言授予事实。
 * 输入为死亡阶段、日期、原死因及可选初始波上下文；记录入口另接收 World 与待写事件数组。
 * 输出为资格布尔值和 last_words_granted 事件；实际生命仍在写入前检查，规则未知则拒绝。
 * 此机制不执行玩家发言、更新死亡波或判胜，发言与阶段推进归原调用流程。
 */
/** 文件说明：遗言规则与事件写入机制。 */
import type { LastWordsPolicy } from "../../../domain/board";
import { AliveComponent } from "../../../domain/components/alive";
import { COMPONENT } from "../../../domain/components/names";
import {
  EntityId,
  GameEvent,
  Phase,
  DeathCause,
  type DeathSources,
} from "../../../domain/model";
import { World } from "../../../domain/world";
import { FRAGRANT_PAIR_POLICY } from "@ai-werewolf-arena/game-contract/facts/fragrant-pair-seer";
export interface LastWordsGrantContext {
  policy: typeof FRAGRANT_PAIR_POLICY;
  initialWave: boolean;
}

/** 遗言机制：判定是否可遗言并写入遗言授权事件。 */
export class LastWordsMechanism {
  /** 这里只判来源阶段、日期与死因；基础政策是否初始波由调用方筛选，不凭资格布尔值直接开放发言。 */
  shouldGrantLastWords(
    deathPhase: Phase,
    day: number,
    sources: readonly DeathCause[],
    policy: LastWordsPolicy = "awa_initial_wave_v1",
    context?: LastWordsGrantContext,
  ): boolean {
    // 具名政策要求全部原因已知，再允许白天／投票及首夜夜死；不借当前执行阶段猜测死亡来源。
    if (policy === "netease_2017_day_and_first_night_v1") {
      if (!sources.length || sources.some((source) => !Object.values(DeathCause).includes(source)))
        return false;
      return (
        deathPhase === Phase.Day ||
        deathPhase === Phase.Voting ||
        (deathPhase === Phase.Night && day === 1)
      );
    }
    if (policy !== "awa_initial_wave_v1") return false;
    if (
      sources.length === 0 ||
      sources.includes(DeathCause.SelfDestruct) ||
      sources.includes(DeathCause.WhiteWolfBlast)
    )
      return false;
    if (deathPhase === Phase.Day && sources.every((source) => source === DeathCause.DuelFailure))
      return true;
    return (
      (deathPhase === Phase.Night &&
        day === 1 &&
        sources.some(
          (source) =>
            source === DeathCause.WolfKill ||
            (source === DeathCause.FragrantLink &&
              context?.policy === FRAGRANT_PAIR_POLICY &&
              context.initialWave) ||
            source === DeathCause.AwakenedHiddenKnife ||
            source === DeathCause.Poison ||
            source === DeathCause.Dream ||
            source === DeathCause.FoxInspection ||
            source === DeathCause.MerchantBacklash ||
            source === DeathCause.BlackMarketBacklash,
        )) ||
      (deathPhase === Phase.Voting && sources.includes(DeathCause.Exile))
    );
  }

  /** 逐人再次核死因政策与实际死亡，只写授予事实；等待玩家、打开生命许可和记录发言归结算器。 */
  recordLastWordsGranted(
    world: World,
    deadIds: EntityId[],
    deathPhase: Phase,
    lastWordsPhase: Phase,
    day: number,
    events: GameEvent[],
    sources: DeathSources,
    deathPhases: Readonly<Record<EntityId, Phase>> = {},
    policy: LastWordsPolicy = "awa_initial_wave_v1",
    context?: LastWordsGrantContext,
  ): void {
    for (const deadId of deadIds) {
      if (
        !this.shouldGrantLastWords(
          deathPhases[deadId] ?? deathPhase,
          day,
          sources[deadId] ?? [],
          policy,
          context,
        )
      ) {
        continue;
      }
      const alive = world.getComponent(deadId, COMPONENT.Alive);
      if (!alive || alive.alive) {
        continue;
      }
      events.push({
        timestamp: Date.now(),
        type: "last_words_granted",
        payload: {
          playerId: deadId,
          phase: lastWordsPhase,
          day,
        },
      });
    }
  }
}

let defaultMechanism: LastWordsMechanism | null = null;

/** 获取默认遗言机制实例。 */
export function getDefaultLastWordsMechanism(): LastWordsMechanism {
  if (!defaultMechanism) {
    defaultMechanism = new LastWordsMechanism();
  }
  return defaultMechanism;
}

/**
 * 负责玩家 checkpoint 的完整外部数据格式与公共记录类型。输入是调用方原正整数／JSON
 * schema 引用和待审核的归档数据；输出保留组合字段、optional 组件与原两项 refine。
 * privateState 仍是 generic JSON 记录，不按当前角色筛槽或套用各族 live schema；合法档案
 * 不能恢复原体、库存或行动许可。普通状态捕获先按原 clone 规则执行，JSON 拒绝仍在随后
 * Tape parse 的原时点；16 个机制 verifier 在格式准入之后按原顺序独立核对因果。
 */
import { z } from "zod";
import { CUPID_POLICIES, SHERIFF_BADGE_POLICIES, Camp, Role } from "@ai-werewolf-arena/game-contract";
import type { VictoryAffiliation } from "@ai-werewolf-arena/game-contract";
import { readVictoryAffiliations } from "@ai-werewolf-arena/replay-contract";

export interface RecordedPlayerState {
  id: number;
  seat: number;
  name: string;
  role: Role;
  camp: Camp;
  alive: boolean;
  privateState: Record<string, unknown>;
  wallNote?: import("../../domain/components/wall-note").WallNoteComponent;
  debatePenalty?: import("../../domain/components/debate-penalty").DebatePenaltyComponent;
  lovers?: import("../../domain/components/lovers").LoversComponent;
  vote: { weight: number; canVote: boolean };
  badge: {
    isSheriff: boolean;
    destroyed: boolean;
    voteWeight: number;
    handoffPolicy?: import("../../domain/board").SheriffBadgePolicy;
  };
  marks: string[];
  victory: { affiliations: VictoryAffiliation[] };
}
/**
 * 使用原 positive／jsonObject 对象形成玩家格式，不复制通用 validator 或提前解析 live 状态。
 * affiliations 的原 reader 失败只形成原 issue；顶层 Tape parser 仍决定拒绝及后续 verifier。
 */
export function createRecordedPlayerSchema(
  positive: z.ZodNumber,
  jsonObject: z.ZodRecord<z.ZodString, z.ZodJSONSchema>,
) {
  const affiliationsSchema = z.unknown().transform((value, ctx): VictoryAffiliation[] => {
    try {
      return readVictoryAffiliations(value);
    } catch {
      ctx.addIssue({ code: "custom", message: "reproduction_affiliations_invalid" });
      return z.NEVER;
    }
  });
  return z
    .strictObject({
      id: positive,
      seat: positive,
      name: z.string(),
      role: z.enum(Role),
      camp: z.enum(Camp),
      alive: z.boolean(),
      // 完整私态保留正常 JSON 扩展和独立能力 metadata；没有当前 Role 白名单。
      privateState: jsonObject,
      // 三个组件各自可缺席；缺席不在这里创建库存、处罚或恋人关系。
      wallNote: z
        .strictObject({
          instanceId: z.string().regex(/^wall:1:[1-9][0-9]*$/),
          source: z.strictObject({
            kind: z.literal("wall_event"),
            eventId: z.literal("awa_wall_notes_v1"),
            day: z.literal(1),
          }),
          remaining: z.union([z.literal(0), z.literal(1)]),
          expired: z.boolean(),
        })
        .optional(),
      debatePenalty: z
        .strictObject({
          day: positive,
          sourceId: positive,
          lifeVersion: z.number().int().nonnegative(),
        })
        .optional(),
      lovers: z
        .strictObject({
          actorId: positive,
          day: z.literal(1),
          policy: z.enum(CUPID_POLICIES),
          pairIds: z.tuple([positive, positive]),
          pairCamps: z.tuple([z.enum([Camp.Good, Camp.Wolf]), z.enum([Camp.Good, Camp.Wolf])]),
          groupId: z.literal("cupid_lovers"),
          mixed: z.boolean(),
        })
        // 仅核归档配对和 mixed 的一致性，真实关系／生命仍由独立 verifier 审核。
        .refine(
          (record) =>
            record.pairIds[0] !== record.pairIds[1] &&
            record.mixed === (record.pairCamps[0] !== record.pairCamps[1]),
          "reproduction_lovers_invalid",
        )
        .optional(),
      victory: z.strictObject({ affiliations: affiliationsSchema }),
      vote: z.strictObject({ weight: z.number().finite().nonnegative(), canVote: z.boolean() }),
      badge: z.strictObject({
        isSheriff: z.boolean(),
        destroyed: z.boolean(),
        voteWeight: z.number().finite().positive(),
        handoffPolicy: z.enum(SHERIFF_BADGE_POLICIES).optional(),
      }),
      marks: z.array(z.string()),
    })
    // 墙实例所属编号在完整字段审核后复验；保留原错误与 optional 短路。
    .refine(
      (player) => !player.wallNote || player.wallNote.instanceId === `wall:1:${player.id}`,
      "reproduction_wall_owner_invalid",
    );
}

/**
 * 负责四族原生／学习枪的完整死亡结算：死因资格、选择等待、原体复验、付款与追加提案。
 * 输入是原 World、死因、选择回调、具体资源贡献和死亡上下文；输出保原对象的提案／延期事实。
 * await 后先核 current 与捕获 stock，再依原角色、学习、政策、来源及原生命复验，失效不付款。
 * pass／映射 miss／保护阻挡按原规则付款；消费先于保护与事实，后续失败保已付前缀。
 * 已退休 Role 只在未消费行动入口与等待后拒绝；原 stock 异常与完整原体检查先行。
 * state 只接晚取阵营 source，普通 Hunter／WolfKing 可忽略；原值比较不升级组件引用撤权。
 * 已消费延期提案保原 isCurrent，不因行动墓碑撤回已付前缀；本 owner 不开许可、标死或封盘。
 */
import type { CurrentCampSource } from "../../../domain/components/camp";
import { isRoleExecutionRetired } from "../../../domain/role-execution-authority";
import {
  captureNativeGunStock,
  consumeNativeDeathGun,
  type NativeDeathGunStockQueries,
} from "./native-death-gun-resources";
import { captureNightLife, livingNightLife } from "../../../domain/night-effects";
import { aliveLifeVersion } from "../../../domain/components/alive";
import { COMPONENT } from "../../../domain/components/names";
import type { RoleComponent } from "../../../domain/components/role";
import {
  DeathCause,
  permitsDeathShot,
  type DeathActionPolicy,
  type EntityId,
  type GameEvent,
  type Role,
  type DeathSources,
  type DeathShotSelection,
} from "../../../domain/model";
import type { World } from "../../../domain/world";
import type { DeathHookResult, DeathHookContext } from "../hooks/hook_registry";

export interface NativeDeathShotRules extends NativeDeathGunStockQueries {
  role: Role;
  state: (
    role: RoleComponent,
    currentCamp: CurrentCampSource,
  ) => { readonly canShoot: boolean; readonly deathActionPolicy?: DeathActionPolicy } | undefined;
  policy?: (state: {
    readonly canShoot: boolean;
    readonly deathActionPolicy?: DeathActionPolicy;
  }) => DeathActionPolicy;
  permits: (sources: readonly DeathCause[]) => boolean;
  shotEvent: (actorId: EntityId, targetId: EntityId) => GameEvent;
  poisonEvent?: (actorId: EntityId) => GameEvent;
}

/** 共用原单枪消费；实际目标死亡和最终判胜仍归中央结算。 */
export async function resolveNativeDeathShots(
  world: World,
  deadIds: EntityId[],
  deathSources: DeathSources,
  choose: (actorId: EntityId) => Promise<DeathShotSelection>,
  events: GameEvent[],
  rules: NativeDeathShotRules,
  context?: DeathHookContext,
): Promise<DeathHookResult> {
  const result: DeathHookResult = { extraDeaths: [], extraDeathSources: {} };
  for (const actorId of deadIds) {
    if (context?.isCurrent && !context.isCurrent()) break;
    const role = world.getComponent(actorId, COMPONENT.Role);
    const state = role ? rules.state(role, () => world.getComponent(actorId, COMPONENT.Camp)) : undefined;
    if (
      !role ||
      role.role !== rules.role ||
      !state ||
      world.getComponent(actorId, COMPONENT.Alive)?.alive !== false
    )
      continue;
    // 原角色／状态／死亡检查已通过，退休只拒未消费行动；不把纯 state 查询变成权限。
    if (isRoleExecutionRetired(role)) continue;
    // 先捕获原审计 stock 再读死因；普通／学习枪仍只写同一 canShoot，不建立影子库存。
    const stock = captureNativeGunStock(rules.role, rules, world, actorId, state);
    const consume = () => consumeNativeDeathGun(state, stock);
    const sources = deathSources[actorId] ?? [];
    if (sources.includes(DeathCause.Poison)) {
      if (isRoleExecutionRetired(role)) continue;
      consume();
      if (rules.poisonEvent) events.push(rules.poisonEvent(actorId));
      continue;
    }
    const policy = rules.policy?.(state);
    const deathPhase = context?.deathOriginPhase;
    const nightEffect = context?.nightEffect;
    const causeIdentity = JSON.stringify(sources);
    if (
      !state.canShoot ||
      !rules.permits(sources) ||
      (policy !== undefined && !permitsDeathShot(sources, policy, deathPhase))
    ) {
      if (isRoleExecutionRetired(role)) continue;
      consume();
      continue;
    }
    const actorLife = world.getComponent(actorId, COMPONENT.Alive)!;
    const actorVersion = aliveLifeVersion(actorLife);
    const camp = world.getComponent(actorId, COMPONENT.Camp)?.camp,
      privateState = role.privateState;
    const targets = new Map(
      world.getAliveEntityIds().map((id) => [id, captureNightLife(world, id)]),
    );
    const selected = await choose(actorId);
    if (context?.isCurrent && !context.isCurrent()) break;
    if (stock && !stock.isCurrent()) throw new Error("demon_hunter_native_hunter_stock_revoked");
    const currentRole = world.getComponent(actorId, COMPONENT.Role);
    if (
      currentRole !== role ||
      currentRole.role !== rules.role ||
      world.getComponent(actorId, COMPONENT.Camp)?.camp !== camp ||
      currentRole.privateState !== privateState ||
      rules.state(currentRole, () => world.getComponent(actorId, COMPONENT.Camp)) !== state ||
      rules.policy?.(state) !== policy ||
      context?.deathOriginPhase !== deathPhase ||
      context?.nightEffect !== nightEffect ||
      JSON.stringify(deathSources[actorId] ?? []) !== causeIdentity ||
      !rules.permits(deathSources[actorId] ?? []) ||
      (policy !== undefined &&
        !permitsDeathShot(deathSources[actorId] ?? [], policy, deathPhase)) ||
      !state.canShoot ||
      world.getComponent(actorId, COMPONENT.Alive) !== actorLife ||
      actorLife.alive ||
      aliveLifeVersion(actorLife) !== actorVersion
    )
      continue;
    // 保原 context→stock 撤权错误→完整原体复验的优先级，然后才拒退休演员，仍未消费。
    if (isRoleExecutionRetired(role)) continue;
    if (
      selected.kind === "invalid" ||
      !world.isDeathActionOpen(actorId, "shoot", selected.deathActionId)
    )
      continue;
    if (selected.kind === "pass") {
      if (isRoleExecutionRetired(role)) continue;
      consume();
      continue;
    }
    if (selected.mappingCurrent && !selected.mappingCurrent()) continue;
    const targetScope = selected.targetScope ?? targets.get(selected.targetId);
    if (selected.mappedMiss) {
      if (
        !selected.mappingCurrent ||
        !targetScope ||
        targetScope.id !== selected.targetId ||
        world.getComponent(targetScope.id, COMPONENT.Alive) !== targetScope.life ||
        targetScope.life.alive ||
        aliveLifeVersion(targetScope.life) !== targetScope.version
      )
        continue;
      if (isRoleExecutionRetired(role)) continue;
      consume();
      events.push({
        timestamp: Date.now(),
        type: "death_shot_missed",
        payload: { actorId, reason: "no_effect" },
      });
      continue;
    }
    if (
      !targetScope ||
      targetScope.id !== selected.targetId ||
      !livingNightLife(world, targetScope)
    )
      continue;
    // 原映射／目标回调可在复验中同步退休演员；全部原检查完成后、消费前再核同一 Role。
    if (isRoleExecutionRetired(role)) continue;
    consume();
    if (context?.nightEffect && context.blocksNightShot(selected.targetId)) {
      events.push({
        timestamp: Date.now(),
        type: "death_shot_blocked",
        payload: { actorId, targetId: selected.targetId, reason: "night_protection" },
      });
      continue;
    }
    result.extraDeaths.push(selected.targetId);
    if (context?.nightEffect) (result.nightEffectTargets ??= []).push(selected.targetId);
    result.extraDeathSources[selected.targetId] = [DeathCause.Shot];
    const event = rules.shotEvent(actorId, selected.targetId);
    if (context?.deferShotCommit)
      (result.pendingShots ??= []).push({
        targetScope,
        event,
        isCurrent: () =>
          (context.isCurrent?.() ?? true) &&
          world.getComponent(actorId, COMPONENT.Role) === role &&
          role.role === rules.role &&
          world.getComponent(actorId, COMPONENT.Camp)?.camp === camp &&
          role.privateState === privateState &&
          rules.state(role, () => world.getComponent(actorId, COMPONENT.Camp)) === state &&
          rules.policy?.(state) === policy &&
          context?.deathOriginPhase === deathPhase &&
          context?.nightEffect === nightEffect &&
          (policy === undefined ||
            permitsDeathShot(deathSources[actorId] ?? [], policy, deathPhase)) &&
          world.getComponent(actorId, COMPONENT.Alive) === actorLife &&
          !actorLife.alive &&
          aliveLifeVersion(actorLife) === actorVersion &&
          JSON.stringify(deathSources[actorId] ?? []) === causeIdentity &&
          world.isDeathActionOpen(actorId, "shoot", selected.deathActionId),
      });
    else events.push(event);
  }
  return result;
}
